/* Group XB (front-end callbacks): fuzz only, no verify wrappers. */

/* Group XC: fuzz only (the callbacks call sound, network, menu and input code by address;
 * the cheap ones are reached through the menu code, already verified). */

/* Group XD: the two fixed menu boxes only write their front-end packets and
 * link them into the sprite list 0x6cdd90 (call tree: fe_box_frame_place
 * 0x431780, its image size lookups and 0x429080, all data section); checked
 * on every call (menu refreshes). The host boxes / player slots (0x452c20,
 * 0x452980) link into the ordering table through 0x6cd518 / 0x6cd520, whose
 * storage I could not place inside the snapshot: fuzz only, like the rest
 * (sound, menu changes and callbacks, GetKeyState, DirectPlay, DirectDraw
 * locks, CD audio). */
